### C++

```cpp
#include <iostream>
#include <vector>
using namespace std;

class SegmentTree {
    vector<int> tree;  // 区间最大值
    vector<int> pos;   // 最大值对应的最小编号
    int n;
public:
    SegmentTree(int size) : n(size) {
        tree.resize(size * 4, 0);
        pos.resize(size * 4, 0);
    }

    void pushUp(int rt) {
        int left = rt << 1;
        int right = rt << 1 | 1;
        tree[rt] = max(tree[left], tree[right]);
        if (tree[left] >= tree[right]) {
            pos[rt] = pos[left];
        } else {
            pos[rt] = pos[right];
        }
    }

    void build(int rt, int l, int r, const vector<int>& arr) {
        if (l == r) {
            tree[rt] = arr[l];
            pos[rt] = l;
            return;
        }
        int m = (l + r) >> 1;
        build(rt << 1, l, m, arr);
        build(rt << 1 | 1, m + 1, r, arr);
        pushUp(rt);
    }

    // 返回 pair<最大值, 位置>
    pair<int, int> query(int rt, int l, int r, int L, int R) {
        if (L <= l && r <= R) {
            return {tree[rt], pos[rt]};
        }
        int m = (l + r) >> 1;
        int mx = -1, p = -1;
        if (L <= m) {
            auto leftRes = query(rt << 1, l, m, L, R);
            mx = leftRes.first;
            p = leftRes.second;
        }
        if (R > m) {
            auto rightRes = query(rt << 1 | 1, m + 1, r, L, R);
            if (rightRes.first > mx) {
                mx = rightRes.first;
                p = rightRes.second;
            }
        }
        return {mx, p};
    }

    void update(int rt, int l, int r, int idx, int val) {
        if (l == r) {
            tree[rt] = val;
            return;
        }
        int m = (l + r) >> 1;
        if (idx <= m) {
            update(rt << 1, l, m, idx, val);
        } else {
            update(rt << 1 | 1, m + 1, r, idx, val);
        }
        pushUp(rt);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<int> a(m + 1, 0); // 1-indexed
    for (int i = 1; i <= m; ++i) {
        cin >> a[i];
    }

    SegmentTree seg(m);
    seg.build(1, 1, m, a);

    vector<int> ans;
    ans.reserve(n);
    for (int i = 0; i < n; ++i) {
        int day, l, r;
        cin >> day >> l >> r;
        auto res = seg.query(1, 1, m, l, r);
        int mx = res.first, p = res.second;
        if (mx < day) {
            ans.push_back(-1);
        } else {
            seg.update(1, 1, m, p, -1);
            ans.push_back(p);
        }
    }

    for (int i = 0; i < n; ++i) {
        cout << ans[i];
        if (i < n - 1) cout << " ";
    }
    cout << "\n";
    return 0;
}
